import React, { useState } from 'react';

function BookingModal({ event, onConfirm, onClose }) {
  const [userName, setUserName] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = () => {
    if (!userName.trim()) {
      setError('Please enter your name.');
      return;
    }
    onConfirm(event.id, userName.trim());
  };

  return (
    <div style={{
      position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
      backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex',
      justifyContent: 'center', alignItems: 'center', zIndex: 1000
    }}>
      <div style={{
        background: 'white', padding: '30px', borderRadius: '8px',
        minWidth: '320px', boxShadow: '0 4px 20px rgba(0,0,0,0.3)'
      }}>
        <h3>Book a Seat</h3>
        <p><strong>Event:</strong> {event.name}</p>
        <p><strong>Available Seats:</strong> {event.available_seats}</p>
        <div style={{ marginBottom: '12px' }}>
          <label>Your Name:</label><br />
          <input
            type="text"
            value={userName}
            onChange={(e) => { setUserName(e.target.value); setError(''); }}
            placeholder="Enter your name"
            style={{ width: '100%', padding: '8px', marginTop: '4px', boxSizing: 'border-box' }}
          />
        </div>
        {error && <p style={{ color: 'red' }}>{error}</p>}
        <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
          <button onClick={onClose} style={{ padding: '8px 16px' }}>Cancel</button>
          <button onClick={handleSubmit} style={{ padding: '8px 16px', backgroundColor: '#4CAF50', color: 'white', border: 'none', cursor: 'pointer' }}>
            Confirm Booking
          </button>
        </div>
      </div>
    </div>
  );
}

export default BookingModal;
